        if ((matching_iid_or_result != 0) && (affected_card_controller != player))
        {
          infinite_casting_cost();
        }
        i = i + 1;
      } while (i < instance->info_slot);
    }
    etb_ability(player, card, EVENT_MODIFY_COST_GLOBAL, RESOLVE_TRIGGER_MANDATORY);
